css_extra:
.termos { display:grid; gap:8px }
.termo { background:var(--b); border:1px solid var(--linha); border-left:4px solid var(--bem); border-radius:10px; padding:7px 11px; font-size:var(--fs-apoio); line-height:1.35 }
.termo b { display:block; color:var(--p); font-size:15.5px; margin-bottom:1px }
.termo code { font-size:.92em }
.barras { display:grid; gap:9px; margin:4px 0 }
.barra { display:grid; grid-template-columns:150px 1fr 56px; align-items:center; gap:10px; font-size:var(--fs-apoio) }
.barra .trilho { position:relative; height:22px; background:var(--azc); border-radius:6px; overflow:hidden }
.barra .enche { position:absolute; inset:0 auto 0 0; background:var(--bem); border-radius:6px }
.barra .enche.base { background:#9CA3AF }
.barra .enche.alvo { background:var(--bem2) }
.barra .meta { position:absolute; top:-3px; bottom:-3px; width:0; border-left:2px dashed var(--er) }
.barra b { text-align:right; font-variant-numeric:tabular-nums }
.legenda-meta { font-size:var(--fs-min); color:var(--er-tx); margin-top:2px }
.pill { display:inline-block; padding:2px 10px; border-radius:999px; font-size:13.5px; font-weight:700; white-space:nowrap }
.pill.ok { background:#E7F6EC; color:#166534; border:1px solid #BBE5C8 }
.pill.parc { background:#FFF6E0; color:#8A5A00; border:1px solid #F3DCA2 }
.pill.nao { background:var(--er-bg); color:var(--er-tx); border:1px solid var(--er-bd) }
.url-demo { font-family:var(--fonte-tit); font-weight:800; font-size:21px; color:var(--bem2); word-break:break-all }
.qr { width:150px; height:150px; image-rendering:pixelated; border-radius:8px; border:1px solid var(--linha); background:#fff; padding:4px }
.evo3 { display:grid; grid-template-columns:repeat(4,1fr); gap:8px; text-align:center }
.evo3 > div { background:var(--b); border:1px solid var(--linha); border-radius:10px; padding:8px 6px }
.evo3 small { display:block; color:var(--tx-apoio); font-size:13px }
.evo3 b { display:block; font-size:24px; color:var(--p) }
.evo3 .fim b { color:var(--bem) }
.mini-tit { font-size:13px; letter-spacing:.06em; text-transform:uppercase; color:var(--tx-apoio); font-weight:700; margin:2px 0 4px }
.seta-fluxo .et { flex:1 1 120px; padding:9px 8px; font-size:var(--fs-apoio); line-height:1.3 }
.seta-fluxo .et b { display:block; font-size:16px; color:var(--p) }
.seta-fluxo .st { font-size:1.4em }
.rec { display:flex; gap:12px; flex-wrap:wrap; margin:2px 0 8px }
.rec span { padding:8px 14px; border-radius:10px; border:1px solid var(--linha); font-weight:700; color:var(--tx-apoio); background:var(--b) }
.rec span.on { background:var(--bem2); color:#fff; border-color:var(--bem2) }

/* ===== IFGuia M3: escala de leitura para projeção (tela grande e PDF; não afeta o modo celular) ===== */
html:not(.movel) { --fs-corpo: 19.5px; --fs-h3: 21px }
html:not(.movel) .sl .slbd.g { font-size: 19.5px !important }
html:not(.movel) .sl .card h3 { font-size: 22px }
html:not(.movel) .sl .card { padding: 15px 20px }
html:not(.movel) .termo { font-size: 18px; padding: 10px 14px; line-height: 1.4 }
html:not(.movel) .termo b { font-size: 20px; margin-bottom: 4px }
html:not(.movel) .fluxo .et { font-size: 16.5px; line-height: 1.3; padding: 12px 10px }
html:not(.movel) .fluxo .et b { display:block; font-size: 18.5px; margin-bottom: 2px }
html:not(.movel) .pergunta { font-size: 19.5px }
html:not(.movel) .pergunta small { font-size: 13px }
html:not(.movel) .chips span { font-size: 16.5px }
html:not(.movel) .faixa-az { font-size: 19.5px; padding: 12px 22px }
html:not(.movel) .faixa-az.fim { font-size: 24px }
html:not(.movel) .kpi b { font-size: 34px }
html:not(.movel) .kpi span { font-size: 16.5px }
html:not(.movel) .card .rod { font-size: 16.5px }
html:not(.movel) .barras { gap: 16px; margin: 10px 0 }
html:not(.movel) .barra { grid-template-columns: 190px 1fr 64px; font-size: 18.5px }
html:not(.movel) .barra .trilho { height: 32px }
html:not(.movel) .legenda-meta { font-size: 15.5px; margin-top: 8px }
html:not(.movel) .evo3 { margin: auto 0 }
html:not(.movel) .evo3 > div { padding: 14px 6px }
html:not(.movel) .evo3 small { font-size: 15px }
html:not(.movel) .evo3 b { font-size: 30px }
html:not(.movel) .evo3 { gap: 6px }
html:not(.movel) .mini-tit { font-size: 15px }

html:not(.movel) #s13 .tb2, html:not(.movel) #s13 .tb2 th { font-size: 17.5px !important }
html:not(.movel) .pill { font-size: 15px; padding: 3px 12px }
html:not(.movel) .rec span { font-size: 18px; padding: 8px 16px }
html:not(.movel) .url-demo { font-size: 23px }
html:not(.movel) .qr { width: 180px; height: 180px }

/* ===== Ajustes por slide (antes eram estilos inline no HTML) ===== */
.termos { flex: 1 1 auto }
#s4 .card.vd { align-items: center; text-align: center }
#s4 .card.vd .rod { align-self: stretch }
#s11 .tb2 td, #s11 .tb2 th { padding-top: 5px; padding-bottom: 5px }
html:not(.movel) #s11 .tb2, html:not(.movel) #s11 .tb2 th { font-size: 18px !important }
.qrbox { flex: 1 1 auto; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; gap: 10px }
.qrbox .rod { font-size: var(--fs-apoio); color: var(--tx-apoio) }
html:not(.movel) .qrbox .qr { width: 190px; height: 190px }
html:not(.movel) .qrbox .rod { font-size: 17px }
